56	// What counts as shipped browser source. Deliberately NOT a hard-coded project
57	// root: every rule in this pack is gated on the DOM API it judges actually
58	// appearing in the file, so the trigger is the API usage itself and the scan can
59	// safely be repo-shaped. A path scope hard-wired to one project's layout would
60	// make every rule match zero files — and pass VACUOUSLY GREEN — in any repo laid
61	// out differently, which is the worst failure mode a check has.
62	//
63	// The one thing the scan must still exclude is test scaffolding: a test that
64	// dispatches a bare event at its own jsdom node, or spins an observer it lets the
65	// test runner collect, is doing something purpose-built and is not adapting to a
66	// host page. That exclusion is expressed directly — by test/vendor path and test
67	// filename — instead of being a side effect of the source root.
68	const SOURCE_EXT = /\.(?:m|c)?[jt]sx?$/;
69	const NOT_SOURCE = [
70	  /(?:^|\/)(?:node_modules|dist|build|out|coverage|vendor|third_party)\//,
71	  /(?:^|\/)(?:tests?|__tests__|__mocks__|spec|fixtures?|mocks?|e2e)\//,
72	  /(?:^|[./-])(?:test|spec|fixture|mock|stub|fake)s?\.[^/]+$/,
73	];
74	export const isSource = (file) => SOURCE_EXT.test(file) && !NOT_SOURCE.some((re) => re.test(file));
75	
76	/** 1-based line number of `index` in `text`. */
77	export const lineOf = (text, index) => text.slice(0, index).split('\n').length;
78	
79	/**
80	 * The balanced bracketed run beginning at the opener at `open` (inclusive of both
81	 * brackets), or null when the source is unbalanced — a half-written file should
82	 * make a check say nothing, never guess. String and template literals are skipped
83	 * so a bracket inside "a(b)" can't be read as syntax.
84	 */
85	export function balanced(src, open) {
86	  let depth = 0;
87	  for (let i = open; i < src.length; i++) {
88	    const c = src[i];
89	    if (c === '"' || c === "'" || c === '`') {
90	      const quote = c;
91	      for (i += 1; i < src.length; i++) {
92	        if (src[i] === '\\') { i += 1; continue; }
93	        if (src[i] === quote) break;
94	      }
95	      continue;
96	    }
97	    if (c === '{' || c === '[' || c === '(') depth += 1;
98	    else if (c === '}' || c === ']' || c === ')') {
99	      depth -= 1;
100	      if (depth === 0) return src.slice(open, i + 1);
101	    }
102	  }
103	  return null;
104	}
