106	/**
107	 * The UI event interfaces that model **real user input**. These are the ones a
108	 * host page's own handlers are written against, so a synthetic one is only a
109	 * faithful stand-in for a user if it looks like what the browser would have
110	 * produced. `CustomEvent` is deliberately absent: it is your own signal to your
111	 * own listener and has no fidelity contract to hold it to.
112	 */
113	export const INPUT_EVENT_CLASSES = [
114	  'KeyboardEvent',
115	  'MouseEvent',
116	  'PointerEvent',
117	  'TouchEvent',
118	  'WheelEvent',
119	  'InputEvent',
120	  'DragEvent',
121	  'CompositionEvent',
122	];
123	
124	const INPUT_EVENT_RE = new RegExp(`\\b(?:${INPUT_EVENT_CLASSES.join('|')})\\b`);
125	
126	/**
127	 * The constructor names in `src` that stand for a real-input event — the classes
128	 * themselves, plus the ONE hop real code actually takes: a local alias assigned
129	 * from them. Picking the constructor by feature (`const Ctor = key ? view.KeyboardEvent
130	 * : view.MouseEvent`) is how a generic `fire()` helper is written, and a matcher
131	 * that only knew the literal class names would look straight past the single
132	 * dispatch site a whole adapter funnels its input through.
133	 */
134	export function inputEventCtors(src) {
135	  const names = new Set(INPUT_EVENT_CLASSES);
136	  const ALIAS = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\n]*)/g;
137	  let m;
138	  while ((m = ALIAS.exec(src))) {
139	    if (INPUT_EVENT_RE.test(m[2])) names.add(m[1]);
140	  }
141	  return names;
142	}
143	
144	/**
145	 * Every `new <ctor>(…)` construction in `src` whose constructor is one of `names`
146	 * (an optional `view.` / `window.` / `globalThis.` receiver is allowed — a content
147	 * script constructing an event for another frame's document must use THAT window's
148	 * constructor). Returns `{ name, index, args, init }`, where `init` is the second
149	 * argument's object literal, or null when the call passes no init literal at all.
150	 */
151	export function eventConstructions(src, names) {
152	  const NEW = /\bnew\s+(?:(?:window|globalThis|self|view|win)\s*\.\s*)?([A-Za-z_$][\w$]*)\s*\(/g;
153	  const out = [];
154	  let m;
155	  while ((m = NEW.exec(src))) {
156	    if (!names.has(m[1])) continue;
157	    const args = balanced(src, NEW.lastIndex - 1);
158	    if (args === null) continue; // unbalanced source: say nothing
159	    const brace = args.indexOf('{');
160	    const init = brace === -1 ? null : balanced(args, brace);
161	    out.push({ name: m[1], index: m.index, args, init });
162	  }
163	  return out;
164	}
165	
166	/** Does an init object literal spread something this check cannot see into? */
167	export const hasSpread = (init) => init !== null && init.includes('...');
