1	import {
2	  finding, stripComments, isSource, lineOf, balanced,
3	  inputEventCtors, eventConstructions, hasSpread,
4	} from './lib.mjs';
5	
6	// A real click or keystroke bubbles. A synthetic one only bubbles if you say so:
7	// `bubbles` defaults to FALSE on every DOM event constructor, so
8	// `el.dispatchEvent(new MouseEvent('click'))` fires an event that reaches
9	// listeners on `el` and stops dead there.
10	//
11	// On your own markup you rarely notice, because you attached the listener to the
12	// node you dispatched at. On a host page you always notice, because you never
13	// attached anything: the app you are driving handles input by DELEGATION, one
14	// listener near its own root, and an event that does not bubble never arrives.
15	// The failure is silent in the worst way — dispatchEvent returns true, no
16	// exception, no console message, and the page simply does not respond. It is
17	// indistinguishable from "the app ignores untrusted events", which is the wrong
18	// conclusion to reach and an expensive one to back out of.
19	//
20	// Scoped to the event interfaces that model REAL USER INPUT (lib.mjs
21	// INPUT_EVENT_CLASSES) at a `dispatchEvent` site. A CustomEvent is your own signal
22	// to your own listener and is legitimately non-bubbling, so it is never judged.
23	// The constructor is resolved through one alias hop, because a generic `fire()`
24	// helper — the shape an adapter that funnels ALL its synthetic input through one
25	// place actually has — picks its constructor by feature rather than naming a class
26	// at the dispatch site. And "dispatched" is resolved through one variable hop for
27	// the same reason: `const ev = new MouseEvent('click'); el.dispatchEvent(ev)` is
28	// the other shape real dispatch code takes, and an inline-only reading would look
29	// straight past it.
30	//
31	// An init literal that spreads something (`{ ...init }`) is beyond what this check
32	// can see, so it says nothing: the fields may well be set by the caller. That is
33	// the deliberate quiet direction — a check on a fidelity contract earns its keep
34	// by never crying wolf on code it cannot read.
35	
36	const DISPATCH = /\.\s*dispatchEvent\s*\(/g;
37	const BUBBLES_TRUE = /\bbubbles\s*:\s*(?:true|!0)\b/;
38	const BUBBLES_ANY = /\bbubbles\s*:/;
39	
40	const rule = {
41	  id: 'synthetic-input-events-bubble',
42	  severity: 'blocking',
43	  description: 'A dispatched user-input event sets bubbles: true',
44	  doc: '.claudinite/local/packs/host-page-adaptation/RULES.md',
45	  why: 'bubbles defaults to false on every event constructor, and a host page handles input by delegation near its own root — a non-bubbling synthetic event never reaches the handler, silently, and reads as "the app ignores untrusted events"',
46	
47	  run(ctx) {
48	    const out = [];
49	    for (const file of ctx.files) {
50	      if (!isSource(file)) continue;
51	      const raw = ctx.read(file);
52	      if (raw === null || !raw.includes('dispatchEvent')) continue;
53	      const src = stripComments(raw);
54	      const ctors = inputEventCtors(src);
55	
56	      // Where the dispatches are: the argument span of every dispatchEvent call
57	      // (an event constructed inline there is dispatched), plus the names of
58	      // locals dispatched bare — `el.dispatchEvent(ev)`.
59	      const spans = [];
60	      const idents = new Set();
61	      DISPATCH.lastIndex = 0;
62	      let call;
63	      while ((call = DISPATCH.exec(src))) {
64	        const open = DISPATCH.lastIndex - 1;
65	        const args = balanced(src, open);
66	        if (args === null) continue;
67	        spans.push([open, open + args.length]);
68	        const bare = /^\(\s*([A-Za-z_$][\w$]*)\s*\)$/.exec(args);
69	        if (bare) idents.add(bare[1]);
70	      }
71	
72	      for (const { name, index, init } of eventConstructions(src, ctors)) {
73	        const inline = spans.some(([a, b]) => index >= a && index < b);
74	        if (!inline && !idents.has(assignedTo(src, index))) continue; // constructed but never dispatched: not input
75	        if (init === null) {
76	          out.push(finding(rule, {
77	            file,
78	            line: lineOf(src, index),
79	            what: `dispatches a ${name} constructed with no init, so it does not bubble`,
80	            fix: `pass { bubbles: true, cancelable: true, composed: true } to the ${name} constructor — a real user event carries all three, and a page that handles input by delegation only ever sees the ones that bubble`,
81	          }));
82	          continue;
83	        }
84	        if (BUBBLES_TRUE.test(init)) continue;
85	        if (hasSpread(init) && !BUBBLES_ANY.test(init)) continue; // spread may set it: unreadable, so silent
86	        out.push(finding(rule, {
87	          file,
88	          line: lineOf(src, index),
89	          what: `dispatches a ${name} that does not set bubbles: true`,
90	          fix: `set bubbles: true in the ${name} init — without it the event stops at the node you dispatched it on and never reaches the delegated handler the host page listens with`,
91	        }));
92	      }
93	    }
94	    return out;
95	  },
96	};
97	
98	// The local a construction is assigned to (`const ev = new MouseEvent(…)` → 'ev'),
99	// or null. One hop, mirroring the one alias hop on the constructor side; a local
100	// built by a call (`const ev = makeEvent()`) constructs nothing this check can see
101	// and stays unjudged. A property target (`foo.bar = …`) is rejected — a bare-ident
102	// dispatch cannot be naming it.
103	function assignedTo(src, index) {
104	  const before = src.slice(Math.max(0, index - 80), index);
105	  const m = /([A-Za-z_$][\w$]*)\s*=\s*$/.exec(before);
106	  if (!m) return null;
107	  const prev = before[m.index - 1];
108	  return prev === '.' ? null : m[1];
109	}
110	
111	export default rule;
