21	// A check context over a literal file map — the same {files, read} surface the
22	// engine's runner passes, with nothing else the rules are allowed to touch.
23	const ctxOf = (files) => ({
24	  files: Object.keys(files),
25	  read: (f) => (f in files ? files[f] : null),
26	});
27	
28	const run = (rule, files) => rule.run(ctxOf(files));
